content.solution_code:
class MagicCrystal {
  #energyStored;

  constructor(initialEnergy) {
    this.#energyStored = Math.max(0, initialEnergy);
  }

  charge(amount) {
    if (amount > 0) {
      this.#energyStored += amount;
    }
  }

  drain(amount) {
    if (amount > 0 && this.#energyStored >= amount) {
      this.#energyStored -= amount;
      return true;
    }
    return false;
  }

  getEnergyLevel() {
    return this.#energyStored;
  }
}

